python3 - <<'EOF'
import os,re,collections

def mod_to_path(m):
    return m.replace('.','/')+'.lean'
def path_to_mod(p):
    return p[:-5].replace('/','.')

allfiles=set()
for root,dirs,files in os.walk('AlgebraicJacobian'):
    for f in files:
        if f.endswith('.lean'):
            allfiles.add(os.path.join(root,f))
allfiles.add('AlgebraicJacobian.lean')

imp_re=re.compile(r'^\s*import\s+([A-Za-z0-9_.]+)')
imports={}
for p in allfiles:
    ims=[]
    for line in open(p,encoding='utf-8',errors='replace'):
        m=imp_re.match(line)
        if m: ims.append(m.group(1))
        elif line.strip() and not line.startswith('--') and not line.startswith('/-') and not line.strip().startswith('set_option') and not line.strip().startswith('import'):
            pass
    imports[p]=ims

# BFS from root
root='AlgebraicJacobian.lean'
seen={root}
stack=[root]
missing=set()
while stack:
    cur=stack.pop()
    for m in imports.get(cur,[]):
        if not m.startswith('AlgebraicJacobian'): continue
        p=mod_to_path(m)
        if p not in allfiles:
            missing.add((cur,m)); continue
        if p not in seen:
            seen.add(p); stack.append(p)

unrooted=sorted(allfiles-seen)
print('total files:',len(allfiles),'rooted:',len(seen),'unrooted:',len(unrooted))
if missing: print('imports pointing nowhere:',sorted(missing)[:10])

# sorry as a term: strip block comments and line comments
def sorry_terms(p):
    s=open(p,encoding='utf-8',errors='replace').read()
    # remove nested block comments
    out=[];i=0;depth=0
    while i<len(s):
        if s.startswith('/-',i):
            depth+=1;i+=2;continue
        if s.startswith('-/',i) and depth>0:
            depth-=1;i+=2;out.append(' ');continue
        if depth==0:
            if s.startswith('--',i):
                j=s.find('\n',i)
                if j<0: break
                i=j;continue
            out.append(s[i])
        i+=1
    txt=''.join(out)
    return len(re.findall(r'(?<![A-Za-z0-9_.])sorry(?![A-Za-z0-9_!?])',txt))

print()
print('=== UNROOTED files WITH sorry as term ===')
n=0
for p in unrooted:
    c=sorry_terms(p)
    if c: print(f'  {c:3d}  {p}'); n+=1
print('count with sorry:',n)
print()
print('=== all unrooted (first 60) ===')
for p in unrooted[:60]: print('  ',p, sorry_terms(p))
EOF
